  "telemetry" -> F.telemetryFeature
  "metrics" -> F.metricsFeature
  "debug" -> F.debugFeature
  "audit" -> F.auditFeature
  "clienttrack" -> F.clienttrackFeature
  "rbac" -> F.rbacFeature
  "netsim" -> F.netsimFeature
  _ -> F.baseFeature
